<?php $page_title='NGOs'; require 'layout.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';try{if($a==='add'){$pdo->prepare('INSERT INTO ngos(name,email,phone,city,address,description,status) VALUES(?,?,?,?,?,?,?)')->execute([trim($_POST['name']),trim($_POST['email']),trim($_POST['phone']),trim($_POST['city']),trim($_POST['address']),trim($_POST['description']),'pending']);flash('success','NGO added for verification.');}elseif($a==='status'){$pdo->prepare('UPDATE ngos SET status=? WHERE id=?')->execute([$_POST['status'],(int)$_POST['id']]);flash('success','NGO status updated.');}}catch(Throwable $e){flash('error',$e->getMessage());}redirect('ngos.php');}
$ngos=$pdo->query('SELECT * FROM ngos ORDER BY created_at DESC')->fetchAll();
?><section class="admin-page-head"><div><span class="kicker">ADMIN / NGO NETWORK</span><h1>NGO Management</h1><p>Verify organizations and maintain the local support network.</p></div></section><section class="admin-form-card"><h2>Add NGO</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><label>NGO name<input name="name" required></label><label>Email<input type="email" name="email"></label><label>Phone<input name="phone"></label><label>City<input name="city"></label><label>Address<input name="address"></label><label>Description<textarea name="description"></textarea></label><button class="btn primary">Add NGO</button></form></section><div class="admin-table-card"><div class="table-wrap"><table><thead><tr><th>NGO</th><th>Contact</th><th>City</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($ngos as $n):?><tr><td><b><?=e($n['name'])?></b><small><?=e($n['description']??'')?></small></td><td><?=e($n['email']?:'—')?><small><?=e($n['phone']?:'')?></small></td><td><?=e($n['city']?:'—')?></td><td><span class="badge <?=badge_class($n['status'])?>"><?=e($n['status'])?></span></td><td><form class="inline-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$n['id']?>"><select name="status"><option>pending</option><option>verified</option><option>suspended</option></select><button class="mini-btn">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php require 'footer.php'; ?>
